/**
 * GPS + heading subscription hook.
 *
 * Wraps navigator.geolocation.watchPosition and an optional magnetometer reader
 * behind thin interfaces so both are injectable for unit testing.
 *
 * Returns:
 * - position: latest GPS fix (null until first reading)
 * - heading: raw magnetometer reading (null until available)
 * - smoothedHeadingDegrees: EMA-smoothed heading (0–360, null until first reading)
 * - isConfident: true when accuracy ≤ maxAccuracyMeters (from isGpsFixConfident)
 * - isHeadingValid: true when magnetometer is available AND accuracyDegrees ≤ 15
 */

import { useEffect, useRef, useState } from 'react';
import { isGpsFixConfident } from '../../src/shared/gps';

/* ──────────────── Types ──────────────── */

/**
 * A single GPS position fix.
 * headingDegrees may be null when the device does not provide it.
 */
export interface PositionFix {
  latitude: number;
  longitude: number;
  accuracyMeters: number;
  headingDegrees: number | null;
  timestamp: number;
}

/**
 * A single magnetometer/compass reading.
 * headingDegrees is 0–360 clockwise from magnetic north.
 * accuracyDegrees estimates heading precision.
 */
export interface HeadingData {
  headingDegrees: number;
  accuracyDegrees: number;
}

/**
 * Abstracts the device magnetometer / compass API.
 * Start/stop lifecycle so the hook controls when the sensor is active.
 */
export interface HeadingReader {
  start(callback: (data: HeadingData) => void): void;
  stop(): void;
}

/**
 * Abstracts navigator.geolocation.watchPosition.
 * Returns a stop handle so the hook can tear down the watcher on unmount.
 */
export interface PositionReader {
  watchPosition(
    onPosition: (fix: PositionFix) => void,
    onError: (error: Error) => void,
  ): { stop: () => void };
}

/* ──────────────── Hook options ──────────────── */

export interface UseCurrentPositionOptions {
  /** Minimum interval between position updates in ms. Default: 2000. */
  updateIntervalMs?: number;
  /** Maximum accuracy (metres) for isConfident. Default: 50. */
  maxAccuracyMeters?: number;
  /** Heading source. Defaults to DefaultNativeHeadingReader. */
  headingReader?: HeadingReader;
  /** Position source. Defaults to DefaultPositionReader. */
  positionReader?: PositionReader;
}

/* ──────────────── Default readers ──────────────── */

/**
 * Default heading reader using the expo-sensors Magnetometer API.
 * Falls back to a no-op if the module is unavailable (e.g. web / no sensor).
 * Maps magnetometer X/Y magnitude to a heading in degrees.
 */
export class DefaultNativeHeadingReader implements HeadingReader {
  private subscription: { remove: () => void } | null = null;

  start(callback: (data: HeadingData) => void): void {
    this.stop();
    try {
      // Dynamic import so this file still compiles without expo-sensors installed.
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      const { Magnetometer } = require('expo-sensors') as {
        Magnetometer: { addListener: (cb: (e: { x: number; y: number }) => void) => { remove: () => void } };
      };
      this.subscription = Magnetometer.addListener((event) => {
        // atan2(y, x) gives angle from magnetic north in radians; + math.PI/2 rotates
        // so 0° points magnetic north, then convert to degrees and normalise 0–360.
        const radians = Math.atan2(event.x, event.y);
        let degrees = ((radians * 180) / Math.PI + 90 + 360) % 360;
        callback({ headingDegrees: degrees, accuracyDegrees: 10 });
      });
    } catch {
      // expo-sensors not available — heading stays null.
    }
  }

  stop(): void {
    this.subscription?.remove();
    this.subscription = null;
  }
}

/**
 * Default position reader using navigator.geolocation.watchPosition.
 * Works in any browser or React Native environment with the Geolocation API.
 */
export class DefaultPositionReader implements PositionReader {
  watchPosition(
    onPosition: (fix: PositionFix) => void,
    onError: (error: Error) => void,
  ): { stop: () => void } {
    let watchId: number;

    const onGeoSuccess = (pos: GeolocationPosition) => {
      onPosition({
        latitude: pos.coords.latitude,
        longitude: pos.coords.longitude,
        accuracyMeters: pos.coords.accuracy ?? Infinity,
        headingDegrees: pos.coords.heading ?? null,
        timestamp: pos.timestamp,
      });
    };

    const onGeoError = (err: GeolocationPositionError) => {
      onError(new Error(`[Geolocation] ${err.message}`));
    };

    watchId = navigator.geolocation.watchPosition(onGeoSuccess, onGeoError, {
      enableHighAccuracy: true,
    });

    return {
      stop() {
        navigator.geolocation.clearWatch(watchId);
      },
    };
  }
}

/* ──────────────── Hook ──────────────── */

export interface UseCurrentPositionReturn {
  position: PositionFix | null;
  heading: HeadingData | null;
  /** EMA-smoothed heading in degrees (0–360). Null until first reading. */
  smoothedHeadingDegrees: number | null;
  isConfident: boolean;
  isHeadingValid: boolean;
}

/**
 * EMA smoothing factor applied per heading update.
 * Higher alpha → faster convergence to new reading.
 */
const HEADING_EMA_ALPHA = 0.3;

/**
 * Maximum magnetometer accuracy (degrees) to trust the heading.
 * Readings with worse accuracy are treated as invalid.
 */
const HEADING_ACCURACY_THRESHOLD_DEG = 15;

/**
 * Subscribes to device position and (optionally) magnetometer heading.
 *
 * Heading EMA handles wraparound at 0°/360° by always moving through the
 * shorter angular path toward the new reading.
 */
export function useCurrentPosition(
  options: UseCurrentPositionOptions = {},
): UseCurrentPositionReturn {
  const {
    maxAccuracyMeters = 50,
    headingReader = new DefaultNativeHeadingReader(),
    positionReader = new DefaultPositionReader(),
  } = options;

  const [position, setPosition] = useState<PositionFix | null>(null);
  const [heading, setHeading] = useState<HeadingData | null>(null);
  const [smoothedHeadingDegrees, setSmoothedHeadingDegrees] = useState<number | null>(null);
  const [isHeadingValid, setIsHeadingValid] = useState(false);

  // Keep the current smoothed heading in a ref so we don't need to re-subscribe
  // on every EMA update.
  const smoothedHeadingRef = useRef<number | null>(null);

  // True once at least one position fix has been received.
  const hasPosition = useRef(false);

  useEffect(() => {
    // ── Position subscription ────────────────────────────────────────────────
    const posHandle = positionReader.watchPosition(
      (fix) => {
        hasPosition.current = true;
        setPosition(fix);
      },
      // Non-fatal: keep the last known position rather than resetting to null.
      () => {},
    );

    // ── Heading subscription ────────────────────────────────────────────────
    headingReader.start((data) => {
      setHeading(data);
      const isValid = data.accuracyDegrees <= HEADING_ACCURACY_THRESHOLD_DEG;
      setIsHeadingValid(isValid);

      if (!isValid) return;

      const raw = data.headingDegrees;
      const current = smoothedHeadingRef.current;

      if (current === null) {
        // First valid reading — no smoothing needed.
        smoothedHeadingRef.current = raw;
        setSmoothedHeadingDegrees(raw);
        return;
      }

      // Compute shortest angular distance from current to new reading.
      let delta = raw - current;
      if (delta > 180) delta -= 360;
      if (delta < -180) delta += 360;

      const smoothed = current + HEADING_EMA_ALPHA * delta;
      // Normalise to 0–360.
      const normalised = ((smoothed % 360) + 360) % 360;

      smoothedHeadingRef.current = normalised;
      setSmoothedHeadingDegrees(normalised);
    });

    return () => {
      posHandle.stop();
      headingReader.stop();
    };
  }, [positionReader, headingReader]); // stable object references — no re-mount on render

  const isConfident = hasPosition.current
    ? position !== null && isGpsFixConfident(position.accuracyMeters, maxAccuracyMeters)
    : false;

  return {
    position,
    heading,
    smoothedHeadingDegrees,
    isConfident,
    isHeadingValid,
  };
}

/**
 * Tests for mobile/hooks/useCurrentPosition.ts
 *
 * Covers:
 * - Confident position with good heading → isConfident=true, isHeadingValid=true
 * - Confident position with no heading → isConfident=true, isHeadingValid=false
 * - Unconfident GPS (accuracy > threshold) → isConfident=false
 * - Heading EMA smoothing: two readings 90° apart smooth toward new value
 * - Cleanup: subscriptions stopped on unmount
 */

import { act, renderHook } from '@testing-library/react';
import { describe, expect, it, vi } from 'vitest';
import type { HeadingData, HeadingReader, PositionFix, PositionReader } from './useCurrentPosition';
import { useCurrentPosition } from './useCurrentPosition';

/* ──────────────── Mock builders ──────────────── */

function makePositionReader(
  fixes: PositionFix[],
): PositionReader {
  let idx = 0;
  return {
    watchPosition(onPosition) {
      // Emit each fix on the next microtask so React can process state updates.
      let timer: ReturnType<typeof setTimeout> | null = null;
      const emit = () => {
        if (idx < fixes.length) {
          act(() => {
            onPosition(fixes[idx]!);
          });
          idx++;
          if (idx < fixes.length) {
            timer = setTimeout(emit, 0);
          }
        }
      };
      timer = setTimeout(emit, 0);
      return {
        stop() {
          if (timer !== null) clearTimeout(timer);
        },
      };
    },
  };
}

function makeHeadingReader(readings: HeadingData[]): HeadingReader {
  let idx = 0;
  let cb: ((data: HeadingData) => void) | null = null;
  return {
    start(callback) {
      cb = callback;
      let timer: ReturnType<typeof setTimeout> | null = null;
      const emit = () => {
        if (idx < readings.length && cb !== null) {
          act(() => {
            cb(readings[idx]!);
          });
          idx++;
          if (idx < readings.length) {
            timer = setTimeout(emit, 0);
          }
        }
      };
      timer = setTimeout(emit, 0);
    },
    stop() {
      cb = null;
    },
  };
}

/* ──────────────── Fixture helpers ──────────────── */

const CONFIDENT_FIX: PositionFix = {
  latitude: 37.42,
  longitude: -122.08,
  accuracyMeters: 10,
  headingDegrees: null,
  timestamp: Date.now(),
};

const UNCONFIDENT_FIX: PositionFix = {
  latitude: 37.42,
  longitude: -122.08,
  accuracyMeters: 200, // > default threshold of 50
  headingDegrees: null,
  timestamp: Date.now(),
};

const HEADING_VALID: HeadingData = {
  headingDegrees: 45,
  accuracyDegrees: 5, // ≤ 15
};

const HEADING_INVALID: HeadingData = {
  headingDegrees: 180,
  accuracyDegrees: 30, // > 15
};

/* ──────────────── Tests ──────────────── */

describe('useCurrentPosition', () => {
  describe('position confidence', () => {
    it('isConfident=true when accuracy ≤ maxAccuracyMeters', () => {
      const reader = makePositionReader([CONFIDENT_FIX]);
      const { result } = renderHook(() => useCurrentPosition({ positionReader: reader }));

      // Wait for async fixes to be processed.
      act(() => {});

      expect(result.current.isConfident).toBe(true);
      expect(result.current.position?.accuracyMeters).toBe(10);
    });

    it('isConfident=false when accuracy > maxAccuracyMeters', () => {
      const reader = makePositionReader([UNCONFIDENT_FIX]);
      const { result } = renderHook(() => useCurrentPosition({ positionReader: reader }));

      act(() => {});

      expect(result.current.isConfident).toBe(false);
      expect(result.current.position?.accuracyMeters).toBe(200);
    });

    it('isConfident=false before any position is received', () => {
      const reader = makePositionReader([]);
      const { result } = renderHook(() => useCurrentPosition({ positionReader: reader }));

      act(() => {});

      expect(result.current.isConfident).toBe(false);
      expect(result.current.position).toBeNull();
    });
  });

  describe('heading validity', () => {
    it('isHeadingValid=true when magnetometer reading accuracy ≤ 15°', () => {
      const posReader = makePositionReader([CONFIDENT_FIX]);
      const headReader = makeHeadingReader([HEADING_VALID]);
      const { result } = renderHook(() =>
        useCurrentPosition({ positionReader: posReader, headingReader: headReader }),
      );

      act(() => {});

      expect(result.current.isHeadingValid).toBe(true);
      expect(result.current.heading?.headingDegrees).toBe(45);
    });

    it('isHeadingValid=false when magnetometer accuracy > 15°', () => {
      const posReader = makePositionReader([CONFIDENT_FIX]);
      const headReader = makeHeadingReader([HEADING_INVALID]);
      const { result } = renderHook(() =>
        useCurrentPosition({ positionReader: posReader, headingReader: headReader }),
      );

      act(() => {});

      expect(result.current.isHeadingValid).toBe(false);
      expect(result.current.heading?.accuracyDegrees).toBe(30);
    });

    it('isHeadingValid=false when no heading reader has been started', () => {
      const posReader = makePositionReader([CONFIDENT_FIX]);
      const headReader = makeHeadingReader([]);
      const { result } = renderHook(() =>
        useCurrentPosition({ positionReader: posReader, headingReader: headReader }),
      );

      act(() => {});

      expect(result.current.isHeadingValid).toBe(false);
      expect(result.current.heading).toBeNull();
    });
  });

  describe('confident position with good heading', () => {
    it('both isConfident and isHeadingValid are true', () => {
      const posReader = makePositionReader([CONFIDENT_FIX]);
      const headReader = makeHeadingReader([HEADING_VALID]);
      const { result } = renderHook(() =>
        useCurrentPosition({ positionReader: posReader, headingReader: headReader }),
      );

      act(() => {});

      expect(result.current.isConfident).toBe(true);
      expect(result.current.isHeadingValid).toBe(true);
    });
  });

  describe('confident position with no heading', () => {
    it('isConfident=true, isHeadingValid=false', () => {
      const posReader = makePositionReader([CONFIDENT_FIX]);
      const headReader = makeHeadingReader([]);
      const { result } = renderHook(() =>
        useCurrentPosition({ positionReader: posReader, headingReader: headReader }),
      );

      act(() => {});

      expect(result.current.isConfident).toBe(true);
      expect(result.current.isHeadingValid).toBe(false);
    });
  });

  describe('EMA heading smoothing', () => {
    it('first valid reading sets smoothedHeadingDegrees directly (no smoothing needed)', () => {
      const posReader = makePositionReader([CONFIDENT_FIX]);
      const headReader = makeHeadingReader([{ headingDegrees: 90, accuracyDegrees: 5 }]);
      const { result } = renderHook(() =>
        useCurrentPosition({ positionReader: posReader, headingReader: headReader }),
      );

      act(() => {});

      expect(result.current.smoothedHeadingDegrees).toBe(90);
    });

    it('second reading 90° apart moves smoothed value toward it by alpha * delta', () => {
      // First reading: 0°
      // Second reading: 90°
      // delta = 90 - 0 = 90
      // alpha = 0.3
      // smoothed = 0 + 0.3 * 90 = 27
      const posReader = makePositionReader([CONFIDENT_FIX]);
      const headReader = makeHeadingReader([
        { headingDegrees: 0, accuracyDegrees: 5 },
        { headingDegrees: 90, accuracyDegrees: 5 },
      ]);
      const { result } = renderHook(() =>
        useCurrentPosition({ positionReader: posReader, headingReader: headReader }),
      );

      act(() => {});

      // After second reading, smoothedHeading should be 0 + 0.3 * 90 = 27
      expect(result.current.smoothedHeadingDegrees).toBeCloseTo(27, 5);
    });

    it('handles wraparound: reading of 10° after 350° moves through 20° (shorter path)', () => {
      // delta from 350 to 10:
      // raw delta = 10 - 350 = -340
      // normalize: -340 + 360 = 20
      // smoothed = 350 + 0.3 * 20 = 356
      const posReader = makePositionReader([CONFIDENT_FIX]);
      const headReader = makeHeadingReader([
        { headingDegrees: 350, accuracyDegrees: 5 },
        { headingDegrees: 10, accuracyDegrees: 5 },
      ]);
      const { result } = renderHook(() =>
        useCurrentPosition({ positionReader: posReader, headingReader: headReader }),
      );

      act(() => {});

      expect(result.current.smoothedHeadingDegrees).toBeCloseTo(356, 5);
    });

    it('handles wraparound the other way: reading of 350° after 10° moves through -20°', () => {
      // delta from 10 to 350:
      // raw delta = 350 - 10 = 340
      // normalize: 340 - 360 = -20
      // smoothed = 10 + 0.3 * (-20) = 4
      const posReader = makePositionReader([CONFIDENT_FIX]);
      const headReader = makeHeadingReader([
        { headingDegrees: 10, accuracyDegrees: 5 },
        { headingDegrees: 350, accuracyDegrees: 5 },
      ]);
      const { result } = renderHook(() =>
        useCurrentPosition({ positionReader: posReader, headingReader: headReader }),
      );

      act(() => {});

      expect(result.current.smoothedHeadingDegrees).toBeCloseTo(4, 5);
    });

    it('smoothedHeadingDegrees stays null when no valid heading reading arrives', () => {
      const posReader = makePositionReader([CONFIDENT_FIX]);
      // Only send invalid readings.
      const headReader = makeHeadingReader([
        { headingDegrees: 0, accuracyDegrees: 30 }, // invalid
        { headingDegrees: 90, accuracyDegrees: 30 }, // invalid
      ]);
      const { result } = renderHook(() =>
        useCurrentPosition({ positionReader: posReader, headingReader: headReader }),
      );

      act(() => {});

      expect(result.current.smoothedHeadingDegrees).toBeNull();
      expect(result.current.isHeadingValid).toBe(false);
    });
  });

  describe('cleanup', () => {
    it('stops position subscription on unmount', () => {
      const stopSpy = vi.fn();
      const posReader: PositionReader = {
        watchPosition() {
          return { stop: stopSpy };
        },
      };
      const headReader: HeadingReader = {
        start() {},
        stop() {},
      };

      const { unmount } = renderHook(() =>
        useCurrentPosition({ positionReader: posReader, headingReader: headReader }),
      );

      unmount();

      expect(stopSpy).toHaveBeenCalledTimes(1);
    });

    it('stops heading subscription on unmount', () => {
      const stopSpy = vi.fn();
      const posReader: PositionReader = {
        watchPosition() {
          return { stop() {} };
        },
      };
      const headReader: HeadingReader = {
        start() {},
        stop: stopSpy,
      };

      const { unmount } = renderHook(() =>
        useCurrentPosition({ positionReader: posReader, headingReader: headReader }),
      );

      unmount();

      expect(stopSpy).toHaveBeenCalledTimes(1);
    });

    it('unmount before any position arrives does not crash', () => {
      const posReader: PositionReader = {
        watchPosition() {
          return { stop: vi.fn() };
        },
      };
      const headReader: HeadingReader = {
        start() {},
        stop: vi.fn(),
      };

      const { unmount } = renderHook(() =>
        useCurrentPosition({ positionReader: posReader, headingReader: headReader }),
      );

      // Unmount immediately — no state ever updated.
      expect(() => unmount()).not.toThrow();
    });
  });

  describe('default readers', () => {
    it('uses DefaultPositionReader when positionReader not provided', () => {
      // Just verify the hook renders without crashing.
      // In jsdom, navigator.geolocation does not exist, so any watchPosition call
      // will throw — but the effect only runs after mount, so render itself succeeds.
      const { result } = renderHook(() => useCurrentPosition({}));
      expect(result.current.position).toBeNull();
    });
  });
});

